package com.reikoonya.musikoo.scrobble

import com.reikoonya.musikoo.BuildConfig
import org.json.JSONObject
import java.io.IOException
import java.net.HttpURLConnection
import java.net.URL
import java.net.URLEncoder
import java.security.MessageDigest

/**
 * Last.fm settings. Get a free key and secret at https://www.last.fm/api/account/create
 * Values are read from local.properties through BuildConfig (see build.gradle.kts).
 */
object LastFmConfig {
    // Values come from BuildConfig, generated by build.gradle.kts from local.properties.
    // No keys in code, so this file is safe to commit.
    val API_KEY: String get() = BuildConfig.LASTFM_API_KEY
    val API_SECRET: String get() = BuildConfig.LASTFM_API_SECRET

    val isConfigured: Boolean
        get() = API_KEY.isNotBlank() && API_SECRET.isNotBlank()
}

/** Error from Last.fm. Codes: 9 means session invalid, 11/16/29 are temporary, others mean invalid data. */
class LastFmException(val code: Int, message: String) : IOException(message)

object LastFmClient {
    private const val ENDPOINT = "https://ws.audioscrobbler.com/2.0/"

    /** Signature: parameters sorted by name, concatenated with their values, plus the secret. format and api_sig are excluded. */
    fun sign(params: Map<String, String>): String {
        val raw = params.toSortedMap().entries.joinToString("") { it.key + it.value } + LastFmConfig.API_SECRET
        return MessageDigest.getInstance("MD5")
            .digest(raw.toByteArray(Charsets.UTF_8))
            .joinToString("") { "%02x".format(it) }
    }

    /** Call only from a background thread. */
    private fun call(method: String, params: Map<String, String>): JSONObject {
        check(LastFmConfig.isConfigured) { "Last.fm is not configured: set the key in LastFmConfig" }

        val all = HashMap(params)
        all["method"] = method
        all["api_key"] = LastFmConfig.API_KEY
        val signed = all + ("api_sig" to sign(all))
        val body = (signed + ("format" to "json")).entries.joinToString("&") {
            encode(it.key) + "=" + encode(it.value)
        }

        val connection = URL(ENDPOINT).openConnection() as HttpURLConnection
        try {
            connection.requestMethod = "POST"
            connection.connectTimeout = 10_000
            connection.readTimeout = 15_000
            connection.doOutput = true
            connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded")
            connection.outputStream.use { it.write(body.toByteArray(Charsets.UTF_8)) }

            val stream = if (connection.responseCode in 200..299) connection.inputStream else connection.errorStream
            val text = stream?.bufferedReader()?.use { it.readText() }.orEmpty()
            val json = JSONObject(text)
            if (json.has("error")) {
                throw LastFmException(json.optInt("error"), json.optString("message"))
            }
            return json
        } finally {
            connection.disconnect()
        }
    }

    private fun encode(value: String): String = URLEncoder.encode(value, "UTF-8")

    /** Login step 1: get a token, which the user confirms on the website. */
    fun getToken(): String = call("auth.getToken", emptyMap()).getString("token")

    fun authUrl(token: String): String =
        "https://www.last.fm/api/auth/?api_key=${LastFmConfig.API_KEY}&token=$token"

    /** Login step 2: after confirmation, exchange the token for a permanent session key. Returns (key, name). */
    fun getSession(token: String): Pair<String, String> {
        val session = call("auth.getSession", mapOf("token" to token)).getJSONObject("session")
        return session.getString("key") to session.getString("name")
    }

    fun updateNowPlaying(sessionKey: String, artist: String, track: String, album: String, durationSec: Long) {
        val params = mutableMapOf("sk" to sessionKey, "artist" to artist, "track" to track)
        if (album.isNotBlank()) params["album"] = album
        if (durationSec > 0) params["duration"] = durationSec.toString()
        call("track.updateNowPlaying", params)
    }

    fun scrobble(
        sessionKey: String,
        artist: String,
        track: String,
        album: String,
        timestamp: Long,
        durationSec: Long,
    ) {
        val params = mutableMapOf(
            "sk" to sessionKey,
            "artist" to artist,
            "track" to track,
            "timestamp" to timestamp.toString()
        )
        if (album.isNotBlank()) params["album"] = album
        if (durationSec > 0) params["duration"] = durationSec.toString()
        call("track.scrobble", params)
    }
}
